-- 리눅스 세트 350. 여러 번 실행해도 안전하다 (NOT EXISTS 가드). 단원·display_order·아이콘은 통합 시 따로 정한다. docs/specs/spec_linux_env_shell_set.md
INSERT INTO quest_set (id, title, description, sandbox_type, category)
SELECT 350, '환경 변수와 쉘 설정: export, env·printenv, PATH 순서, VAR=값 명령, unset, ${VAR:-기본값}, 설정 파일·source, alias', '작은 실습 폴더로 환경 변수와 쉘 설정을 한 단계씩 익힙니다. export 한 변수와 하지 않은 변수를 자식 bash 로 비교하고, env·printenv 로 값을 보고, 실습 폴더를 PATH 에 붙이거나 앞에 둬서 이름만으로 실행하고, 명령 한 번에만 변수를 주고, unset 과 기본값 ${VAR:-값} 을 쓰며, 설정 파일에 적어 source 하고 alias 를 더하고 unalias 로 지웁니다. 채점은 결과를 저장한 파일의 내용과, 새 쉘에서 설정 파일을 읽어 얻은 실제 값을 기대값과 비교합니다.', 'linux', '리눅스'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest_set WHERE id = 350);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 1, '변수를 만들고 자식 프로세스에 넘기기 (export)', '변수 두 개를 만듭니다. `LAB_A` 는 값 `one` 으로 **그냥** 만들고, `LAB_B` 는 값 `two` 로 만들되 **자식 프로그램에도 전달**되게 하세요. 그런 다음 자식 `bash` 가 각 변수를 어떻게 보는지 파일에 남깁니다. 자식 bash 가 `[$LAB_A]` 를 출력한 결과를 **`/tmp/lab/plain.txt`** 에, `[$LAB_B]` 를 출력한 결과를 **`/tmp/lab/exported.txt`** 에 저장하세요. (대괄호까지 포함해서 저장합니다.)', '`bash -c ''명령''` 은 새 bash(자식)를 띄워 명령을 실행합니다. `$LAB_A` 를 안쪽에서 해석하도록 작은따옴표로 감싸세요. 변수를 자식에게 넘기려면 `export` 를 씁니다. 결과는 `>` 로 파일에 보냅니다.', 'LAB_A=one
export LAB_B=two
bash -c ''echo "[$LAB_A]"'' > /tmp/lab/plain.txt
bash -c ''echo "[$LAB_B]"'' > /tmp/lab/exported.txt
cat /tmp/lab/plain.txt /tmp/lab/exported.txt

# export 하지 않은 변수는 자식에게 보이지 않아 [] 가 된다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/tools /tmp/lab/new /tmp/lab/old\\nprintf ''#!/bin/sh\\\\necho \\"hello from lab tools\\"\\\\necho ran >> /tmp/lab/ran.log\\\\n'' > /tmp/lab/tools/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"new version\\"\\\\n'' > /tmp/lab/new/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"old version\\"\\\\n'' > /tmp/lab/old/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"mode=[$APP_MODE]\\"\\\\necho \\"$APP_MODE\\" >> /tmp/lab/seen.log\\\\n'' > /tmp/lab/showenv.sh\\nprintf ''# lab rc\\\\nexport LAB_LEVEL=1\\\\n'' > /tmp/lab/my_bashrc\\nprintf \\"alias ll=''ls -l''\\\\nalias rm=''rm -i''\\\\nalias cp=''cp -i''\\\\n\\" > /tmp/lab/aliasrc\\nchmod +x /tmp/lab/tools/hello-lab /tmp/lab/new/hello-lab /tmp/lab/old/hello-lab /tmp/lab/showenv.sh\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/plain.txt | cut -d\\" \\" -f1)\\" = \\"58e0494c51d30eb3494f7c9198986bb9\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/exported.txt | cut -d\\" \\" -f1)\\" = \\"cb729a15bceceb05f599b14f3bd12dd1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "plain.txt 가 [] 이다 (export 안 한 변수는 자식에게 안 보인다)", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/plain.txt | cut -d\\" \\" -f1)\\" = \\"58e0494c51d30eb3494f7c9198986bb9\\" ]"]}, {"label": "exported.txt 가 [two] 이다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/exported.txt | cut -d\\" \\" -f1)\\" = \\"cb729a15bceceb05f599b14f3bd12dd1\\" ]"]}]', '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 1);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 2, '환경 변수 보기 (env, printenv)', '환경 변수 `LAB_TOKEN` 을 값 `k7x2` 로 만들어 자식 프로그램이 볼 수 있게 하세요. 그런 다음 (1) `LAB_TOKEN` 의 **값만** **`/tmp/lab/value.txt`** 에, (2) 환경 변수 전체 목록 중 `LAB_TOKEN` 이 든 **줄**을 **`/tmp/lab/env_line.txt`** 에 저장하세요.', '`printenv 이름` 은 그 환경 변수의 값만 출력하고, `env` 는 환경 변수 전체를 `이름=값` 줄로 출력합니다. 전체 목록에서 한 줄만 고르려면 `grep` 으로 걸러 보세요. 줄이 `^LAB_TOKEN=` 로 시작하는 것만 고르면 정확합니다.', 'export LAB_TOKEN=k7x2
printenv LAB_TOKEN > /tmp/lab/value.txt
env | grep ''^LAB_TOKEN='' > /tmp/lab/env_line.txt
cat /tmp/lab/value.txt /tmp/lab/env_line.txt

# printenv 이름 은 값만, env 는 이름=값 전체', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/tools /tmp/lab/new /tmp/lab/old\\nprintf ''#!/bin/sh\\\\necho \\"hello from lab tools\\"\\\\necho ran >> /tmp/lab/ran.log\\\\n'' > /tmp/lab/tools/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"new version\\"\\\\n'' > /tmp/lab/new/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"old version\\"\\\\n'' > /tmp/lab/old/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"mode=[$APP_MODE]\\"\\\\necho \\"$APP_MODE\\" >> /tmp/lab/seen.log\\\\n'' > /tmp/lab/showenv.sh\\nprintf ''# lab rc\\\\nexport LAB_LEVEL=1\\\\n'' > /tmp/lab/my_bashrc\\nprintf \\"alias ll=''ls -l''\\\\nalias rm=''rm -i''\\\\nalias cp=''cp -i''\\\\n\\" > /tmp/lab/aliasrc\\nchmod +x /tmp/lab/tools/hello-lab /tmp/lab/new/hello-lab /tmp/lab/old/hello-lab /tmp/lab/showenv.sh\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/value.txt | cut -d\\" \\" -f1)\\" = \\"0c7ff20ada6f5739cbfab6d2981c542a\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/env_line.txt | cut -d\\" \\" -f1)\\" = \\"8928d15ed5bad59119698dc880f69bca\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "value.txt 가 k7x2 이다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/value.txt | cut -d\\" \\" -f1)\\" = \\"0c7ff20ada6f5739cbfab6d2981c542a\\" ]"]}, {"label": "env_line.txt 가 LAB_TOKEN=k7x2 한 줄이다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/env_line.txt | cut -d\\" \\" -f1)\\" = \\"8928d15ed5bad59119698dc880f69bca\\" ]"]}]', '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 2);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 3, '실습 폴더를 PATH 뒤에 붙여 이름만으로 실행하기', '`/tmp/lab/tools` 폴더에 실행 파일 `hello-lab` 이 있습니다. 지금은 `hello-lab` 만 입력하면 "command not found" 가 납니다. **기존 PATH 는 그대로 두고 뒤에** 이 폴더를 붙여, 이름만으로 실행되게 하세요. 그런 다음 (1) `hello-lab` 의 출력을 **`/tmp/lab/hello_out.txt`** 에, (2) 바뀐 PATH 값 전체를 **`/tmp/lab/path.txt`** 에 저장하세요.', 'PATH 는 `:` 로 폴더를 이은 한 줄입니다. 기존 값을 `$PATH` 로 불러와 뒤에 `:새폴더` 를 붙이고, 다시 `export` 하세요. `PATH=새폴더` 처럼 덮어쓰면 `ls` 같은 기본 명령까지 못 찾게 되니 조심합니다. 현재 값은 `echo "$PATH"` 로 봅니다.', 'export PATH=$PATH:/tmp/lab/tools
hello-lab > /tmp/lab/hello_out.txt
echo "$PATH" > /tmp/lab/path.txt
cat /tmp/lab/hello_out.txt

# $PATH:새폴더 : 기존 PATH 뒤에 새 폴더를 붙인다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/tools /tmp/lab/new /tmp/lab/old\\nprintf ''#!/bin/sh\\\\necho \\"hello from lab tools\\"\\\\necho ran >> /tmp/lab/ran.log\\\\n'' > /tmp/lab/tools/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"new version\\"\\\\n'' > /tmp/lab/new/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"old version\\"\\\\n'' > /tmp/lab/old/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"mode=[$APP_MODE]\\"\\\\necho \\"$APP_MODE\\" >> /tmp/lab/seen.log\\\\n'' > /tmp/lab/showenv.sh\\nprintf ''# lab rc\\\\nexport LAB_LEVEL=1\\\\n'' > /tmp/lab/my_bashrc\\nprintf \\"alias ll=''ls -l''\\\\nalias rm=''rm -i''\\\\nalias cp=''cp -i''\\\\n\\" > /tmp/lab/aliasrc\\nchmod +x /tmp/lab/tools/hello-lab /tmp/lab/new/hello-lab /tmp/lab/old/hello-lab /tmp/lab/showenv.sh\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/hello_out.txt | cut -d\\" \\" -f1)\\" = \\"bdcf088cc044f0ec0cff45d11125fc26\\" ] ) && ( [ \\"$(tr -d \\"\\\\n\\" < /tmp/lab/path.txt | awk -F: ''{print $NF}'')\\" = \\"/tmp/lab/tools\\" ] ) && ( grep -q \\"/usr/bin\\" /tmp/lab/path.txt ) && ( [ -s /tmp/lab/ran.log ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "hello_out.txt 에 hello-lab 의 출력이 있다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/hello_out.txt | cut -d\\" \\" -f1)\\" = \\"bdcf088cc044f0ec0cff45d11125fc26\\" ]"]}, {"label": "path.txt 의 맨 끝 폴더가 /tmp/lab/tools 이다", "cmd": ["sh", "-c", "[ \\"$(tr -d \\"\\\\n\\" < /tmp/lab/path.txt | awk -F: ''{print $NF}'')\\" = \\"/tmp/lab/tools\\" ]"]}, {"label": "기존 PATH(/usr/bin)가 지워지지 않고 남아 있다", "cmd": ["sh", "-c", "grep -q \\"/usr/bin\\" /tmp/lab/path.txt"]}, {"label": "hello-lab 이 실제로 실행된 기록이 있다", "cmd": ["sh", "-c", "[ -s /tmp/lab/ran.log ]"]}]', '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 3);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 4, '같은 이름이 두 곳에 있을 때: PATH 순서와 command -v', '`/tmp/lab/new` 와 `/tmp/lab/old` 에 **같은 이름** `hello-lab` 이 하나씩 있습니다 (출력은 각각 `new version`, `old version`). 두 폴더를 모두 PATH 에 넣되 **`new` 가 먼저 선택**되게 하세요. 그런 다음 (1) `hello-lab` 이 어디 것으로 해석되는지 **`/tmp/lab/where.txt`** 에, (2) `hello-lab` 의 출력을 **`/tmp/lab/ver.txt`** 에, (3) PATH 값 전체를 **`/tmp/lab/path4.txt`** 에 저장하세요.', 'PATH 는 **앞에 적힌 폴더부터** 찾습니다. 새 폴더를 앞에 두려면 `export PATH=새폴더:...:$PATH` 처럼 씁니다. 이름이 어디로 해석되는지는 `command -v 이름` 이 경로로 알려 줍니다.', 'export PATH=/tmp/lab/new:/tmp/lab/old:$PATH
command -v hello-lab > /tmp/lab/where.txt
hello-lab > /tmp/lab/ver.txt
echo "$PATH" > /tmp/lab/path4.txt
cat /tmp/lab/where.txt /tmp/lab/ver.txt

# PATH 는 앞쪽 폴더가 먼저 이긴다. command -v 는 실행될 경로를 보여 준다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/tools /tmp/lab/new /tmp/lab/old\\nprintf ''#!/bin/sh\\\\necho \\"hello from lab tools\\"\\\\necho ran >> /tmp/lab/ran.log\\\\n'' > /tmp/lab/tools/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"new version\\"\\\\n'' > /tmp/lab/new/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"old version\\"\\\\n'' > /tmp/lab/old/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"mode=[$APP_MODE]\\"\\\\necho \\"$APP_MODE\\" >> /tmp/lab/seen.log\\\\n'' > /tmp/lab/showenv.sh\\nprintf ''# lab rc\\\\nexport LAB_LEVEL=1\\\\n'' > /tmp/lab/my_bashrc\\nprintf \\"alias ll=''ls -l''\\\\nalias rm=''rm -i''\\\\nalias cp=''cp -i''\\\\n\\" > /tmp/lab/aliasrc\\nchmod +x /tmp/lab/tools/hello-lab /tmp/lab/new/hello-lab /tmp/lab/old/hello-lab /tmp/lab/showenv.sh\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/where.txt | cut -d\\" \\" -f1)\\" = \\"aeefe670eaf7f5556bb4b95ad3ee339e\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/ver.txt | cut -d\\" \\" -f1)\\" = \\"3532d11855ca175f717185077d3ca4ca\\" ] ) && ( awk -F: ''{for(i=1;i<=NF;i++){gsub(/[ \\\\n]/,\\"\\",$i); if($i==\\"/tmp/lab/new\\")a=i; if($i==\\"/tmp/lab/old\\")b=i}} END{exit !(a>0&&b>0&&a<b)}'' /tmp/lab/path4.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "where.txt 가 new 쪽 경로이다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/where.txt | cut -d\\" \\" -f1)\\" = \\"aeefe670eaf7f5556bb4b95ad3ee339e\\" ]"]}, {"label": "ver.txt 가 new version 이다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/ver.txt | cut -d\\" \\" -f1)\\" = \\"3532d11855ca175f717185077d3ca4ca\\" ]"]}, {"label": "path4.txt 에 new 와 old 가 모두 있고 new 가 먼저다", "cmd": ["sh", "-c", "awk -F: ''{for(i=1;i<=NF;i++){gsub(/[ \\\\n]/,\\"\\",$i); if($i==\\"/tmp/lab/new\\")a=i; if($i==\\"/tmp/lab/old\\")b=i}} END{exit !(a>0&&b>0&&a<b)}'' /tmp/lab/path4.txt"]}]', '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 4);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 5, '명령 한 번에만 변수 주기 (VAR=값 명령)', '`/tmp/lab/showenv.sh` 는 환경 변수 `APP_MODE` 를 `mode=[...]` 로 출력하는 스크립트입니다. (1) `APP_MODE` 를 `debug` 로 **이 실행 한 번에만** 주어 실행하고 그 출력을 **`/tmp/lab/once.txt`** 에, (2) 그다음 변수를 따로 주지 않고 실행한 출력을 **`/tmp/lab/after.txt`** 에 저장하세요. 중간에 `export` 를 쓰지 않습니다.', '`변수=값 명령` 처럼 명령 바로 앞에 쓰면 그 명령 하나에만 환경 변수가 전달되고 끝나면 사라집니다. 스크립트는 `/tmp/lab/showenv.sh` 처럼 경로로 실행합니다.', 'APP_MODE=debug /tmp/lab/showenv.sh > /tmp/lab/once.txt
/tmp/lab/showenv.sh > /tmp/lab/after.txt
cat /tmp/lab/once.txt /tmp/lab/after.txt

# 변수=값 명령 : 그 명령 한 번에만 적용, 다음 줄에는 남지 않는다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/tools /tmp/lab/new /tmp/lab/old\\nprintf ''#!/bin/sh\\\\necho \\"hello from lab tools\\"\\\\necho ran >> /tmp/lab/ran.log\\\\n'' > /tmp/lab/tools/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"new version\\"\\\\n'' > /tmp/lab/new/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"old version\\"\\\\n'' > /tmp/lab/old/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"mode=[$APP_MODE]\\"\\\\necho \\"$APP_MODE\\" >> /tmp/lab/seen.log\\\\n'' > /tmp/lab/showenv.sh\\nprintf ''# lab rc\\\\nexport LAB_LEVEL=1\\\\n'' > /tmp/lab/my_bashrc\\nprintf \\"alias ll=''ls -l''\\\\nalias rm=''rm -i''\\\\nalias cp=''cp -i''\\\\n\\" > /tmp/lab/aliasrc\\nchmod +x /tmp/lab/tools/hello-lab /tmp/lab/new/hello-lab /tmp/lab/old/hello-lab /tmp/lab/showenv.sh\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/once.txt | cut -d\\" \\" -f1)\\" = \\"acbc588037b430c00d58e4fb4f0b1670\\" ] ) && ( [ \\"$(md5sum < /tmp/lab/after.txt | cut -d\\" \\" -f1)\\" = \\"2b56ce09db46cad8e336d7cb70294c64\\" ] ) && ( [ \\"$(head -n1 /tmp/lab/seen.log)\\" = \\"debug\\" ] && [ \\"$(wc -l < /tmp/lab/seen.log)\\" -ge 2 ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "once.txt 가 mode=[debug] 이다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/once.txt | cut -d\\" \\" -f1)\\" = \\"acbc588037b430c00d58e4fb4f0b1670\\" ]"]}, {"label": "after.txt 가 mode=[] 이다 (값이 남지 않았다)", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/after.txt | cut -d\\" \\" -f1)\\" = \\"2b56ce09db46cad8e336d7cb70294c64\\" ]"]}, {"label": "스크립트가 두 번 이상 실행된 기록이 있고 첫 실행 값은 debug 이다", "cmd": ["sh", "-c", "[ \\"$(head -n1 /tmp/lab/seen.log)\\" = \\"debug\\" ] && [ \\"$(wc -l < /tmp/lab/seen.log)\\" -ge 2 ]"]}]', '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 5);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 6, 'VAR=값 명령 과 export VAR=값 의 차이는?', '`LOG=1 ./run.sh` 처럼 명령 앞에 변수를 붙이는 방식과, `export LOG=1` 로 미리 설정해 두는 방식을 비교합니다. 둘의 차이는 무엇일까요?', '변수가 **언제까지** 자식 프로그램에게 보이는지를 생각해 보세요. 한 줄이 끝난 뒤 같은 터미널에서 다른 명령을 실행하면 어떻게 되나요?', NULL, NULL, '[]', 'choice', '["`VAR=값 명령` 은 이후 실행하는 자식에게도 계속 전달되고, `export` 는 그 명령 한 번에만 전달된다", "`VAR=값 명령` 은 그 명령 한 번에만 전달되고, `export` 는 이후 실행하는 자식에게도 계속 전달된다", "`VAR=값 명령` 은 값이 파일에 저장되고, `export` 는 메모리에만 잠시 남는다", "`VAR=값 명령` 은 root 만 쓸 수 있고, `export` 는 일반 사용자도 쓸 수 있다"]', 1, '`LOG=1 ./run.sh` 는 그 실행 한 번에만 `LOG` 가 전달되고, 명령이 끝나면 현재 쉘에는 아무 것도 남지 않습니다. `export LOG=1` 은 현재 쉘의 변수를 환경 변수로 올려 두므로, 이후 이 쉘에서 띄우는 모든 자식에게 계속 전달됩니다. 두 방식 모두 파일에 저장하지 않고 쉘이 끝나면 사라지며, 사용 권한에도 차이가 없습니다. 영구히 남기려면 설정 파일에 적어야 합니다.', NULL, NULL, NULL, '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 6);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 7, '변수 지우기 (unset)', '환경 변수 `LAB_SECRET` 을 값 `s3` 로 만들어 자식 프로그램이 볼 수 있게 한 뒤 (1) `printenv LAB_SECRET` 의 출력을 **`/tmp/lab/before.txt`** 에 저장하세요. 그다음 이 변수를 **없애고**, (2) 같은 `printenv LAB_SECRET` 의 출력을 **`/tmp/lab/after.txt`** 에, (3) 그 명령의 종료 코드(`$?`)를 **`/tmp/lab/status.txt`** 에 저장하세요. 값을 빈 문자열로 바꾸는 것이 아니라 변수 자체를 없애야 합니다.', '`unset 이름` 은 변수를 아예 없앱니다. `printenv 이름` 은 변수가 없으면 아무것도 출력하지 않고 종료 코드 1 로 끝납니다. 종료 코드는 직전 명령 직후에 `echo $?` 로 보고, `$?` 가 바뀌기 전에 파일로 보내야 합니다.', 'export LAB_SECRET=s3
printenv LAB_SECRET > /tmp/lab/before.txt
unset LAB_SECRET
printenv LAB_SECRET > /tmp/lab/after.txt
echo $? > /tmp/lab/status.txt
cat /tmp/lab/before.txt /tmp/lab/status.txt

# unset 은 변수를 없앤다. LAB_SECRET= 로 비우는 것과 다르다 (그러면 printenv 가 빈 줄을 출력하고 종료 코드 0)', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/tools /tmp/lab/new /tmp/lab/old\\nprintf ''#!/bin/sh\\\\necho \\"hello from lab tools\\"\\\\necho ran >> /tmp/lab/ran.log\\\\n'' > /tmp/lab/tools/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"new version\\"\\\\n'' > /tmp/lab/new/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"old version\\"\\\\n'' > /tmp/lab/old/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"mode=[$APP_MODE]\\"\\\\necho \\"$APP_MODE\\" >> /tmp/lab/seen.log\\\\n'' > /tmp/lab/showenv.sh\\nprintf ''# lab rc\\\\nexport LAB_LEVEL=1\\\\n'' > /tmp/lab/my_bashrc\\nprintf \\"alias ll=''ls -l''\\\\nalias rm=''rm -i''\\\\nalias cp=''cp -i''\\\\n\\" > /tmp/lab/aliasrc\\nchmod +x /tmp/lab/tools/hello-lab /tmp/lab/new/hello-lab /tmp/lab/old/hello-lab /tmp/lab/showenv.sh\\ntrue"]', '["sh", "-c", "( [ \\"$(md5sum < /tmp/lab/before.txt | cut -d\\" \\" -f1)\\" = \\"083f3f32bd0d1688e418ac4dca898c97\\" ] ) && ( [ -f /tmp/lab/after.txt ] && [ ! -s /tmp/lab/after.txt ] ) && ( [ \\"$(md5sum < /tmp/lab/status.txt | cut -d\\" \\" -f1)\\" = \\"b026324c6904b2a9cb4b88d6d61c81d1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "before.txt 가 s3 이다", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/before.txt | cut -d\\" \\" -f1)\\" = \\"083f3f32bd0d1688e418ac4dca898c97\\" ]"]}, {"label": "after.txt 가 비어 있다 (변수가 없다)", "cmd": ["sh", "-c", "[ -f /tmp/lab/after.txt ] && [ ! -s /tmp/lab/after.txt ]"]}, {"label": "status.txt 가 1 이다 (printenv 가 변수를 못 찾았다)", "cmd": ["sh", "-c", "[ \\"$(md5sum < /tmp/lab/status.txt | cut -d\\" \\" -f1)\\" = \\"b026324c6904b2a9cb4b88d6d61c81d1\\" ]"]}]', '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 7);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 8, '값이 없을 때만 기본값 쓰기 (${VAR:-기본값})', '변수 `NAME` 이 없을 때 `guest` 를 **대신 쓰되 변수 자체는 바꾸지 않는** 코드를 만듭니다. 실행하면 아래 두 줄이 나와야 합니다: 첫 줄 `guest`, 둘째 줄 `[]`. 빈칸에 알맞은 연산자를 채우세요.', '`${변수 연산자 값}` 에서 연산자가 `-` 계열이면 "비었을 때 쓸 값", `=` 계열이면 "비었을 때 쓸 값을 변수에도 넣음" 입니다. 둘째 줄이 `[]` 이어야 한다는 점에 주목하세요.', NULL, NULL, '[]', 'fill', '[":-", ":=", ":+", ":?"]', NULL, '`${NAME:-guest}` 는 `NAME` 이 없거나 비었을 때 `guest` 를 돌려주기만 하고 `NAME` 자체는 그대로 둡니다. 그래서 둘째 줄이 `[]` 입니다. `:=` 는 `guest` 를 변수에도 대입해서 둘째 줄이 `[guest]` 가 됩니다. `:+` 는 변수가 있을 때만 값을 쓰므로 첫 줄이 빈 줄이 되고, `:?` 는 변수가 없으면 오류 메시지를 내고 멈춥니다.', '[0]', 'unset NAME; echo "${NAME{0}guest}"; echo "[$NAME]"', NULL, '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 8);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 9, '기본값이 있는 스크립트 만들기 (${NAME:-guest})', '`/tmp/lab/greet.sh` 를 만드세요. 환경 변수 `NAME` 이 있으면 `hello, 이름` 을, **없거나 비어 있으면** `hello, guest` 를 한 줄로 출력하는 쉘 스크립트입니다. 채점은 `NAME` 을 지운 채로, `Ann` 으로, 빈 값으로 각각 `bash /tmp/lab/greet.sh` 를 실행해 출력을 봅니다.', '파일은 `echo` 와 `>` 로 만들 수 있고, 안쪽의 `$` 가 지금 쉘에서 풀리지 않도록 작은따옴표로 감싸세요. 스크립트 안에서는 `${NAME:-guest}` 형태를 쓸 수 있습니다. 직접 `NAME=Ann bash /tmp/lab/greet.sh` 처럼 돌려 확인해 보세요.', 'echo ''echo "hello, ${NAME:-guest}"'' > /tmp/lab/greet.sh
bash /tmp/lab/greet.sh
NAME=Ann bash /tmp/lab/greet.sh

# :- 는 변수가 없거나 빈 값일 때 기본값을 쓴다 (- 만 쓰면 빈 값은 그대로 통과)', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/tools /tmp/lab/new /tmp/lab/old\\nprintf ''#!/bin/sh\\\\necho \\"hello from lab tools\\"\\\\necho ran >> /tmp/lab/ran.log\\\\n'' > /tmp/lab/tools/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"new version\\"\\\\n'' > /tmp/lab/new/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"old version\\"\\\\n'' > /tmp/lab/old/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"mode=[$APP_MODE]\\"\\\\necho \\"$APP_MODE\\" >> /tmp/lab/seen.log\\\\n'' > /tmp/lab/showenv.sh\\nprintf ''# lab rc\\\\nexport LAB_LEVEL=1\\\\n'' > /tmp/lab/my_bashrc\\nprintf \\"alias ll=''ls -l''\\\\nalias rm=''rm -i''\\\\nalias cp=''cp -i''\\\\n\\" > /tmp/lab/aliasrc\\nchmod +x /tmp/lab/tools/hello-lab /tmp/lab/new/hello-lab /tmp/lab/old/hello-lab /tmp/lab/showenv.sh\\ntrue"]', '["sh", "-c", "( [ \\"$(env -u NAME bash /tmp/lab/greet.sh)\\" = \\"hello, guest\\" ] ) && ( [ \\"$(NAME=Ann bash /tmp/lab/greet.sh)\\" = \\"hello, Ann\\" ] ) && ( [ \\"$(NAME= bash /tmp/lab/greet.sh)\\" = \\"hello, guest\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "NAME 이 없으면 hello, guest", "cmd": ["sh", "-c", "[ \\"$(env -u NAME bash /tmp/lab/greet.sh)\\" = \\"hello, guest\\" ]"]}, {"label": "NAME=Ann 이면 hello, Ann", "cmd": ["sh", "-c", "[ \\"$(NAME=Ann bash /tmp/lab/greet.sh)\\" = \\"hello, Ann\\" ]"]}, {"label": "NAME 이 빈 값이어도 hello, guest", "cmd": ["sh", "-c", "[ \\"$(NAME= bash /tmp/lab/greet.sh)\\" = \\"hello, guest\\" ]"]}]', '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 9);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 10, '설정 파일에 적고 적용하기', '홈 폴더의 `lab_rc` 같은 설정 파일에 변수 설정을 저장하고 지금 쉘에 적용합니다. 처음 상태 확인부터 적용 결과 확인까지, **앞에서 뒤**로 놓으세요.', '파일에 적은 줄은 쉘이 그 파일을 읽어 들이기 전까지 현재 쉘에 아무 영향이 없습니다. 적용 전과 후를 같은 명령으로 비교하는 흐름을 떠올려 보세요.', NULL, NULL, '[]', 'order', '["먼저 `echo $LAB_COLOR` 로 설정 전에는 값이 비어 있음을 확인한다", "`echo ''export LAB_COLOR=blue'' >> ~/lab_rc` 로 설정 파일 끝에 한 줄을 덧붙인다", "`source ~/lab_rc` 로 그 파일을 지금 쉘에 읽어 들인다", "`echo $LAB_COLOR` 를 다시 실행해 blue 가 나오는지 확인한다"]', NULL, '**전 상태 확인 → 파일에 적기 → source 로 적용 → 후 상태 확인** 순서입니다. 파일에 줄을 적는 것만으로는 현재 쉘이 바뀌지 않고, `source` 로 읽어야 비로소 적용됩니다. 적용 뒤 같은 `echo` 를 다시 돌려 값이 바뀐 것을 확인해야 설정이 맞게 들어갔는지 알 수 있습니다. `>>` 는 이어쓰기이고 `>` 는 파일을 덮어써 기존 설정을 지우니 주의합니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 10);

INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs)
SELECT 350, 11, '설정 파일에 환경 변수와 PATH 적기 (source)', '`/tmp/lab/my_bashrc` 는 이미 `export LAB_LEVEL=1` 한 줄이 들어 있는 설정 파일입니다. **기존 줄은 지우지 말고** 아래 두 설정을 이 파일에 더하세요. (1) 환경 변수 `LAB_COLOR` 를 `blue` 로 (자식에게도 전달), (2) `/tmp/lab/tools` 를 PATH 에 추가. 채점은 새 쉘에서 이 파일을 `source` 한 결과를 봅니다. 현재 쉘에서 직접 `export` 한 것은 채점에 보이지 않습니다.', '파일 끝에 줄을 덧붙일 때는 `>>` 를 씁니다. `>` 는 파일을 통째로 덮어씁니다. 파일 안에 `$PATH` 가 그대로 적히게 하려면 작은따옴표로 감싸세요. 다 쓰고 `source /tmp/lab/my_bashrc` 와 `cat` 으로 직접 확인해 보세요.', 'echo ''export LAB_COLOR=blue'' >> /tmp/lab/my_bashrc
echo ''export PATH=$PATH:/tmp/lab/tools'' >> /tmp/lab/my_bashrc
cat /tmp/lab/my_bashrc
source /tmp/lab/my_bashrc

# >> 는 이어쓰기. 작은따옴표로 감싸야 $PATH 가 파일에 글자 그대로 적힌다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/tools /tmp/lab/new /tmp/lab/old\\nprintf ''#!/bin/sh\\\\necho \\"hello from lab tools\\"\\\\necho ran >> /tmp/lab/ran.log\\\\n'' > /tmp/lab/tools/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"new version\\"\\\\n'' > /tmp/lab/new/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"old version\\"\\\\n'' > /tmp/lab/old/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"mode=[$APP_MODE]\\"\\\\necho \\"$APP_MODE\\" >> /tmp/lab/seen.log\\\\n'' > /tmp/lab/showenv.sh\\nprintf ''# lab rc\\\\nexport LAB_LEVEL=1\\\\n'' > /tmp/lab/my_bashrc\\nprintf \\"alias ll=''ls -l''\\\\nalias rm=''rm -i''\\\\nalias cp=''cp -i''\\\\n\\" > /tmp/lab/aliasrc\\nchmod +x /tmp/lab/tools/hello-lab /tmp/lab/new/hello-lab /tmp/lab/old/hello-lab /tmp/lab/showenv.sh\\ntrue"]', '["sh", "-c", "( [ \\"$(env -i PATH=/usr/bin:/bin bash -c ''source /tmp/lab/my_bashrc; printenv LAB_COLOR'')\\" = \\"blue\\" ] ) && ( [ \\"$(env -i PATH=/usr/bin:/bin bash -c ''source /tmp/lab/my_bashrc; command -v hello-lab'')\\" = \\"/tmp/lab/tools/hello-lab\\" ] ) && ( [ \\"$(env -i PATH=/usr/bin:/bin bash -c ''source /tmp/lab/my_bashrc; printenv LAB_LEVEL'')\\" = \\"1\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "새 쉘에서 source 하면 LAB_COLOR 가 blue 로 전달된다", "cmd": ["sh", "-c", "[ \\"$(env -i PATH=/usr/bin:/bin bash -c ''source /tmp/lab/my_bashrc; printenv LAB_COLOR'')\\" = \\"blue\\" ]"]}, {"label": "source 하면 hello-lab 이 PATH 로 찾아진다", "cmd": ["sh", "-c", "[ \\"$(env -i PATH=/usr/bin:/bin bash -c ''source /tmp/lab/my_bashrc; command -v hello-lab'')\\" = \\"/tmp/lab/tools/hello-lab\\" ]"]}, {"label": "기존 설정 LAB_LEVEL=1 이 그대로 남아 있다", "cmd": ["sh", "-c", "[ \\"$(env -i PATH=/usr/bin:/bin bash -c ''source /tmp/lab/my_bashrc; printenv LAB_LEVEL'')\\" = \\"1\\" ]"]}]', '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 11);

