SELECT 350, 12, '별칭 추가하고 하나는 없애기 (alias, unalias)', '`/tmp/lab/aliasrc` 에는 별칭 `ll`, `rm`, `cp` 세 줄이 있습니다. 이 파일을 고쳐서, `source` 했을 때 (1) 새 별칭 `lt` 가 `ls -t` 로 정의되고, (2) 위험한 별칭 `rm` 은 **없어지고**, (3) `ll` 과 `cp` 는 그대로 남게 하세요. 현재 쉘의 별칭이 아니라 **파일의 내용**이 채점 대상입니다.', '별칭은 `alias 이름=''명령''` 로 만들고 `unalias 이름` 으로 없앱니다. 파일에서 줄을 지우거나, 파일 끝에 `unalias` 줄을 덧붙이는 방법이 모두 가능합니다. `alias 이름` 만 쓰면 정의를 보여 주니 `source` 한 뒤 직접 확인해 보세요.', 'echo "alias lt=''ls -t''" >> /tmp/lab/aliasrc
echo ''unalias rm'' >> /tmp/lab/aliasrc
bash -c ''source /tmp/lab/aliasrc; alias''

# 파일 끝에 unalias 를 덧붙이면 source 할 때 앞에서 만든 rm 별칭이 사라진다', '["sh", "-c", "rm -rf /tmp/lab\\nmkdir -p /tmp/lab/tools /tmp/lab/new /tmp/lab/old\\nprintf ''#!/bin/sh\\\\necho \\"hello from lab tools\\"\\\\necho ran >> /tmp/lab/ran.log\\\\n'' > /tmp/lab/tools/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"new version\\"\\\\n'' > /tmp/lab/new/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"old version\\"\\\\n'' > /tmp/lab/old/hello-lab\\nprintf ''#!/bin/sh\\\\necho \\"mode=[$APP_MODE]\\"\\\\necho \\"$APP_MODE\\" >> /tmp/lab/seen.log\\\\n'' > /tmp/lab/showenv.sh\\nprintf ''# lab rc\\\\nexport LAB_LEVEL=1\\\\n'' > /tmp/lab/my_bashrc\\nprintf \\"alias ll=''ls -l''\\\\nalias rm=''rm -i''\\\\nalias cp=''cp -i''\\\\n\\" > /tmp/lab/aliasrc\\nchmod +x /tmp/lab/tools/hello-lab /tmp/lab/new/hello-lab /tmp/lab/old/hello-lab /tmp/lab/showenv.sh\\ntrue"]', '["sh", "-c", "( [ \\"$(bash -c ''source /tmp/lab/aliasrc; alias lt'')\\" = \\"alias lt=''ls -t''\\" ] ) && ( ! bash -c ''source /tmp/lab/aliasrc; alias rm'' >/dev/null 2>&1 ) && ( [ \\"$(bash -c ''source /tmp/lab/aliasrc; alias ll'')\\" = \\"alias ll=''ls -l''\\" ] ) && ( [ \\"$(bash -c ''source /tmp/lab/aliasrc; alias cp'')\\" = \\"alias cp=''cp -i''\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "lt 가 ls -t 별칭으로 정의된다", "cmd": ["sh", "-c", "[ \\"$(bash -c ''source /tmp/lab/aliasrc; alias lt'')\\" = \\"alias lt=''ls -t''\\" ]"]}, {"label": "rm 별칭은 없어진다", "cmd": ["sh", "-c", "! bash -c ''source /tmp/lab/aliasrc; alias rm'' >/dev/null 2>&1"]}, {"label": "ll 별칭은 그대로다", "cmd": ["sh", "-c", "[ \\"$(bash -c ''source /tmp/lab/aliasrc; alias ll'')\\" = \\"alias ll=''ls -l''\\" ]"]}, {"label": "cp 별칭은 그대로다", "cmd": ["sh", "-c", "[ \\"$(bash -c ''source /tmp/lab/aliasrc; alias cp'')\\" = \\"alias cp=''cp -i''\\" ]"]}]', '[{"title": "bash 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/bash.1.html"}, {"title": "env 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/env.1.html"}, {"title": "printenv 매뉴얼 (man7.org)", "url": "https://man7.org/linux/man-pages/man1/printenv.1.html"}, {"title": "환경 변수 개요 environ(7) (man7.org)", "url": "https://man7.org/linux/man-pages/man7/environ.7.html"}, {"title": "export 매뉴얼 POSIX (man7.org)", "url": "https://man7.org/linux/man-pages/man1/export.1p.html"}]'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM quest WHERE quest_set_id = 350 AND order_index = 12);

